{
  "patch_key": "pk:1d787a1e81cefe26",
  "changed_files": [
    "distribution/install.sh"
  ],
  "replay": {
    "scenario": "installer",
    "run": "20261127T035748Z",
    "label": "wording"
  },
  "files": [
    {
      "path": "distribution/install.sh",
      "decisions": [
        {
          "id": "ADR-0585",
          "title": "The installer downloads release assets over the direct route",
          "status": "Proposed",
          "rule": "install.sh consults no GitHub API endpoint and does not read GITHUB_TOKEN",
          "reason": "Anonymous GitHub API requests are limited to 60 per hour per IP address, and users behind shared egress (VPNs, corporate NAT, Cloudflare WARP) exhausted that quota, so the one-line installer broke. Release assets are now fetched over the direct download route instead. Only ADR-0068's installer authentication clause is superseded; version selection still uses releases.json.",
          "decision_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/docs/adr/0585-installer-downloads-via-direct-route.md#L8-L38",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/distribution/install.sh#L120-L128",
          "commit": "5ac38808",
          "commit_url": "https://github.com/relatedb/relate/commit/5ac38808547d11f55b02333624cc3e88b46566eb",
          "checks": [
            {
              "name": "drift guard: install.sh consults no GitHub API endpoint (ADR-0585)",
              "kind": "static",
              "number_at_pin": 7,
              "url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/scripts/tests/test_install_sh.sh#L129-L135",
              "evidence": "the script spells a GitHub API endpoint",
              "observed": "ok",
              "tap_number": 7
            },
            {
              "name": "token set: no Authorization header anywhere (GITHUB_TOKEN never rides a request)",
              "kind": "runtime",
              "number_at_pin": 64,
              "url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/scripts/tests/test_install_sh.sh#L314-L315",
              "evidence": "an install with GITHUB_TOKEN set sent an Authorization header",
              "observed": "ok",
              "tap_number": 64
            },
            {
              "name": "no case made a GitHub API request (ADR-0585)",
              "kind": "runtime",
              "number_at_pin": 193,
              "url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/scripts/tests/test_install_sh.sh#L610-L615",
              "evidence": "a GitHub API request was attempted and recorded in the harness's stubbed curl log",
              "observed": "ok",
              "tap_number": 193
            }
          ]
        }
      ],
      "also_cites": [
        {
          "id": "ADR-0115",
          "title": "Sign release checksums with SSHSIG for offline install and upgrade verification",
          "status": "Accepted",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/distribution/install.sh#L9"
        },
        {
          "id": "ADR-0250",
          "title": "Release discovery from a static releases.json on the website",
          "status": "Accepted",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/distribution/install.sh#L43"
        },
        {
          "id": "ADR-0431",
          "title": "Extension distribution — the first-party channel, the install verbs, and trust tiers (LABS-469)",
          "status": "Proposed",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/distribution/install.sh#L217"
        },
        {
          "id": "ADR-0457",
          "title": "The signed release manifest carries the release version",
          "status": "Proposed",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/distribution/install.sh#L33"
        },
        {
          "id": "ADR-0586",
          "title": "Windows installs through a PowerShell installer",
          "status": "Proposed",
          "citation_url": "https://github.com/relatedb/relate/blob/5f7a510713c3feac146133e77d8c5bb72bae1b11/distribution/install.sh#L83"
        }
      ]
    }
  ],
  "note": "\"observed\" is the check's result in Patch Precedent's replay of this exact patch (matched by its changed lines, ignoring whitespace and context) against the unmodified upstream harness; \"not observed\" means no replay of this patch was found, or that replay produced no result for this check."
}

